    accuracy = IterableTolerance(atol=0.01, rtol=0.01, ulps=4)
    input_dict = {"x": x, "accuracy": accuracy}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 9: 1D float32 array with small fractions
