    list_of_inputs.append(copy.deepcopy({"x": x}))

    # Input 5: 2D int32 array covering boundary values
    x = np.array([[-2147483648, 2147483647], [0, -1]], dtype=np.int32)
    list_of_inputs.append(copy.deepcopy({"x": x}))

    # Input 6: 3D int32 array
