import copy
import numpy as np


class AxisStr(str):

    def __new__(cls, val):
        obj = super().__new__(cls, val)
        obj._val = int("".join(val))
        return obj

    def __index__(self):
        return getattr(self, "_val", int(float("".join(self))))


