class _ConfigList(list):

    def __init__(self, parent_dict):
        super().__init__()
        self.parent_dict = parent_dict

    def __iter__(self):
        if self.parent_dict is not None:
            self.parent_dict["configs"] = None
        return super().__iter__()

    def __len__(self):
        return 0


