    # Input 8: 1D array with all positive values
    x = np.abs(np.random.randn(8).astype(np.float32)) + 0.1
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 9: 5D array
    x = np.random.randn(1, 2, 2, 2, 2).astype(np.float32)
