    # Input 3: Boolean arrays (1D)
    x = np.array([True, True, False, False], dtype=np.bool_)
    y = np.array([True, False, True, False], dtype=np.bool_)
    list_of_inputs.append(copy.deepcopy({"x": x, "y": y}))

