import numpy as np


def compress_inputs():
    list_of_inputs = []

    # Input 1: 1D array, standard boolean mask
    condition = np.array([True, False, True, True], dtype=bool)
    a = np.array([10, 20, 30, 40], dtype=np.int32)
    axis = 0
    size = 3
    fill_value = 0
    list_of_inputs.append(
        copy.deepcopy(
            {
                "condition": condition,
                "a": a,
                "axis": axis,
                "size": size,
                "fill_value": fill_value,
            }
        )
    )

