class StringFunction(str):

    def __new__(cls, expr):
        obj = super().__new__(cls, expr)
        obj._fn = eval(expr)
        return obj

    def __call__(self, *args, **kwargs):
        return self._fn(*args, **kwargs)

    def __deepcopy__(self, memo):
        return StringFunction(str(self))


