    # Input 10: Integer arrays with int64
    x1 = np.array([[[1, 0, 0]], [[0, 1, 0]]], dtype=np.int64)
    x2 = np.array([[[0, 1, 0]], [[0, 0, 1]]], dtype=np.int64)
