    input_dict = {"x": x, "ord": StrOrd("1"), "axis": -1, "keepdims": True}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 3: 2D float32, ord='inf', axis=0, keepdims=False
    x = np.random.randn(3, 4).astype(np.float32)
