import copy
import numpy as np


class Order(str):
    def __new__(cls, val):
        instance = super().__new__(cls, str(val))
        instance.val = val
        return instance

    def __eq__(self, other):
        return other == self.val or super().__eq__(other)

    def __hash__(self):
        return hash(self.val)

    def lower(self):
        return self

    def upper(self):
        return self

    def __int__(self):
        return int(self.val)

    def __float__(self):
        return float(self.val)

    def __reduce__(self):
        return (Order, (self.val,))


