    keepdims = False
    initial = np.array(-np.inf, dtype=np.float64)
    where = np.array([[True, True], [False, True]], dtype=bool)
    list_of_inputs.append(
        copy.deepcopy(
            {
                "a": a,
                "axis": axis,
                "keepdims": keepdims,
                "initial": initial,
                "where": where,
            }
        )
    )

    # Input 4: 3D int64 array, negative axis
