    axis = -1
    keepdims = True
    initial = np.array(-50, dtype=np.int64)
    where = np.ones((2, 3, 4), dtype=bool)
    where[0, 1, 2] = False
    list_of_inputs.append(
        copy.deepcopy(
            {
                "a": a,
                "axis": axis,
                "keepdims": keepdims,
                "initial": initial,
                "where": where,
            }
        )
    )

    # Input 5: 1D int16 array
