    input_dict = {"a": a, "axis": 1, "keepdims": False}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 8: 3D array, negative axis=-3, keepdims=True
    a = rng.standard_normal((4, 2, 3)).astype(np.float32)
