    w = np.ones(M, dtype=np.float64)
    list_of_inputs.append(
        {
            "x": x,
            "y": y,
            "deg": 1,
            "rcond": 1e-6,
            "full": False,
            "w": w,
            "cov": False,
        }
    )

    # Input 2: 1D y, deg=2, full=True, cov=False, float32
    M = 8
