    list_of_inputs = []

    # Input 1: 1D float32 array with common angles
    x = np.array([0.0, np.pi / 6, np.pi / 4, np.pi / 2, np.pi], dtype=np.float32)
    list_of_inputs.append(copy.deepcopy({"x": x}))

