    list_of_inputs.append(copy.deepcopy({"x": x}))

    # Input 7: Float16 array
    x = np.array([-1.5, -0.5, 0.0, 0.5, 1.5], dtype=np.float16)
    list_of_inputs.append(copy.deepcopy({"x": x}))

    # Input 8: Complex64 array
