    dtype = np.int32
    keepdims = False
    initial = np.array(0, dtype=np.int32)
    where = a > 0
    promote_integers = True
    list_of_inputs.append(
        copy.deepcopy(
            {
                "a": a,
                "axis": axis,
                "dtype": dtype,
                "keepdims": keepdims,
                "initial": initial,
                "where": where,
                "promote_integers": promote_integers,
            }
        )
    )

    # Input 4: 2D int32 array, axis 0, keepdims True
