    list_of_inputs.append(copy.deepcopy({"x": x}))

    # Input 11: 5D float32 array
    x = np.ones((1, 2, 1, 3, 2), dtype=np.float32)
    list_of_inputs.append(copy.deepcopy({"x": x}))

