    filt = np.array([0, 0, 2, 0, 1, 4, 3, 0, 0, 0], dtype=np.int32)
    input_dict = {"filt": filt, "trim": "fb", "axis": [0]}
    list_of_inputs.append(copy.deepcopy(input_dict))

