    filt = np.array([0.0, 0.0, -1.5, 3.2, -0.5, 0.0], dtype=np.float32)
    input_dict = {"filt": filt, "trim": "f", "axis": [0]}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 3: 2D float64 array, trimming trailing zeros along axis 0
    filt = np.array(
        [[0.0, 1.0, 0.0], [2.0, -3.0, 0.0], [0.0, 0.0, 0.0]], dtype=np.float64
    )
    input_dict = {"filt": filt, "trim": "b", "axis": [0]}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 4: 2D int64 array, trimming both leading and trailing zeros along axis 1
    filt = np.array(
        [[0, 1, 2, 0], [0, 3, 4, 0], [0, 0, 5, 0]], dtype=np.int64
    )
    input_dict = {"filt": filt, "trim": "fb", "axis": [1]}
