    code_book = np.array([[1.0, 2.0, 3.0]], dtype=np.float32)
    list_of_inputs.append(
        copy.deepcopy(
            {"obs": obs, "code_book": code_book, "check_finite": False}
        )
    )

    # Input 7: Higher-dimensional features (large N)
