import numpy as np
import copy

class WindowParam:
    def __init__(self, val=1.0):
        self.val = float(val)

    def __lt__(self, other):
        if isinstance(other, str):
            return False
        return self.val < getattr(other, "val", other)

    def __gt__(self, other):
        if isinstance(other, str):
            return True
        return self.val > getattr(other, "val", other)

    def __le__(self, other):
        if isinstance(other, str):
            return False
        return self.val <= getattr(other, "val", other)

    def __ge__(self, other):
        if isinstance(other, str):
            return True
        return self.val >= getattr(other, "val", other)

    def __float__(self):
        return self.val

    def __int__(self):
        return int(self.val)

