    list_of_inputs.append({"p": copy.deepcopy(p)})

    # Input 6: 2D array, float64
    rng = np.random.default_rng(42)
    p = rng.uniform(0.01, 0.99, size=(4, 5)).astype(np.float64)
    list_of_inputs.append({"p": copy.deepcopy(p)})

    # Input 7: 3D array, float32
