    list_of_inputs.append({"p": copy.deepcopy(p)})

    # Input 9: Extreme values near 0 and 1, float64
    p = np.array([1e-12, 1e-6, 0.5, 1.0 - 1e-6, 1.0 - 1e-12], dtype=np.float64)
    list_of_inputs.append({"p": copy.deepcopy(p)})

    # Input 10: Empty 1D array, float32
