    beta = np.full((2, 3, 4), 1.5, dtype=np.float32)
    list_of_inputs.append(copy.deepcopy({"x": x, "beta": beta}))

    # Input 8: Extreme tail values
    x = np.array([-50.0, -10.0, 0.0, 10.0, 50.0], dtype=np.float32)
