    beta = np.array([0.2, 0.3, 0.5], dtype=np.float32)
    list_of_inputs.append(copy.deepcopy({"x": x, "beta": beta}))

    # Input 10: Large beta values (approaching uniform)
    x = np.linspace(-2.0, 2.0, 6, dtype=np.float64)
