    x = np.random.randn(2, 2, 2, 2).astype(np.float32)
    beta = (np.random.rand(2, 2, 2, 2) + 0.5).astype(np.float32)
    list_of_inputs.append(copy.deepcopy({"x": x, "beta": beta}))

    return list_of_inputs


