    x = np.array([-2.5, -1.0, 0.0, 1.0, 2.5], dtype=np.float64)
    loc = np.array([0.0, -0.5, 0.0, 0.5, 0.0], dtype=np.float64)
    scale = np.array([1.0, 2.0, 0.5, 1.5, 3.0], dtype=np.float64)
