    list_of_inputs.append(copy.deepcopy({"x": x, "loc": loc, "scale": scale}))

    # Input 4: Broadcasting 1D to 2D
    x = np.linspace(-3.0, 3.0, 10, dtype=np.float32).reshape(10, 1)
    loc = np.array([0.0, 1.0, -1.0], dtype=np.float32).reshape(1, 3)
