    list_of_inputs.append(
        copy.deepcopy({"x": x, "a": a, "b": b, "loc": loc, "scale": scale})
    )

    # Input 4: Broadcasting with different shapes
    x = np.linspace(-1.0, 1.0, 5, dtype=np.float32).reshape(5, 1)
    a = np.array([-3.0], dtype=np.float32)
